import React, { forwardRef, useMemo } from 'react';
import styled, { CSSObject } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Typography from '@dynatrace/strato-design-tokens/typography';

// #region Typings
/** Accepted properties for KeyboardShortcut */
export interface KeyboardShortcutProps {
  /**
   * The list of keys the component should display, specified in the aria-keyshortcuts format.
   */
  keys: string;
  /**
   * The variant that should be used for styling the keys.
   * @defaultValue 'default'
   */
  variant?: 'default' | 'minimal';
  /**
   * The color scheme that should be used.
   * @defaultValue 'neutral'
   */
  color?: 'neutral' | 'onaccent';
  /**
   * Whether the component should be rendered in a disabled state.
   * @defaultValue 'false'
   */
  disabled?: boolean;
}
// #endregion Typings

// #region StyledComponents
const StyledKey = /* @__PURE__ */ styled('kbd')<{
  $variant: 'default' | 'minimal';
  $color: 'neutral' | 'onaccent';
  $disabled: boolean;
}>(({ $variant, $color, $disabled }) => {
  const baseStyles = {
    display: 'inline-block',
    fontSize: Typography.Text.Small.Default.Size,
    fontFamily: Typography.Text.Small.Default.Family,
    fontWeight: Typography.Text.Small.Default.Weight,
    lineHeight: Typography.Text.Small.Default.LineHeight,
    color:
      $color === 'onaccent' && $variant === 'minimal'
        ? Colors.Text.OnAccent.Default
        : Colors.Text.Neutral.Subdued,
    //fix stlyes when injecting doc styles
    boxShadow: 'none',
    background: 'none',
    border: 'none',
    padding: 0,
  };

  const defaultStyles = {
    padding: `0 calc(${Spacings.Size4} - ${Borders.Width.Default})`,
    height: Spacings.Size20,
    // Explicit lineHeight of 18px to ensure vertical alignment in text because of the shortcut's smaller font
    lineHeight: '18px',
    background: `${Colors.Background.Surface.Default}`,
    border: `${Borders.Width.Default} ${Borders.Style.Default} ${Colors.Border.Neutral.Default}`,
    borderRadius: Borders.Radius.Field.Subdued,
    minWidth: Spacings.Size20,
    textAlign: 'center',
    boxSizing: 'border-box',

    '&:not(:last-of-type)': {
      marginRight: Spacings.Size2,
    },
  };

  const plusStyles = {
    '&:not(:last-of-type)::after': {
      content: "'+'",
      display: 'inline-block',
      padding: `0 ${Spacings.Size2}`,
    },
  };

  if ($disabled && $color === 'neutral') {
    baseStyles.color = Colors.Text.Neutral.Disabled;
    defaultStyles.background = Colors.Background.Field.Neutral.Disabled;
    defaultStyles.border = `${Borders.Width.Default} ${Borders.Style.Default} ${Colors.Border.Neutral.Disabled}`;
  } else if ($disabled && $color === 'onaccent') {
    baseStyles.color = Colors.Text.OnAccent.Disabled;
    defaultStyles.background = Colors.Background.Field.OnAccent.Disabled;
    defaultStyles.border = `${Borders.Width.Default} ${Borders.Style.Default} ${Colors.Border.OnAccent.Disabled}`;
  }

  return {
    ...baseStyles,
    ...($variant === 'default' && defaultStyles),
    ...($variant === 'minimal' && plusStyles),
  } as CSSObject;
});

const StyledKeyWrapper = /* @__PURE__ */ styled('kbd')({
  // fix styles when injecting doc styles
  background: 'none',
  border: 'none',
  boxShadow: 'none',
  padding: 0,
});
// #endregion StyledComponents

const keyMappings: Record<string, string> = {
  meta: 'Cmd',
  control: 'Ctrl',
  escape: 'Esc',
  altgraph: 'Option',
  delete: 'Del',
  arrowup: '↑',
  arrowdown: '↓',
  arrowright: '→',
  arrowleft: '←',
  plus: '+',
};

export function createKeyArrayFromString(keys: string): string[] {
  return keys
    .split(' ')[0]
    .split('+')
    .filter((key) => key !== '')
    .map(
      (key) =>
        keyMappings[key.toLowerCase()] ??
        `${key.charAt(0).toUpperCase()}${key.slice(1)}`,
    );
}

/**
 * The `KeyboardShortcut` component visualizes one or multiple keys to communicate keyboard shortcuts for certain actions.
 * To specify a shortcut, provide the key sequence in the {@link https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-keyshortcuts | aria-keyshortcuts} format.
 */
export const KeyboardShortcut = forwardRef<HTMLElement, KeyboardShortcutProps>(
  (props, forwardedRef) => {
    const {
      keys,
      variant = 'default',
      color = 'neutral',
      disabled = false,
      ...remainingProps
    } = props;

    const keyArray = useMemo(() => createKeyArrayFromString(keys), [keys]);

    return (
      <StyledKeyWrapper
        ref={forwardedRef}
        aria-disabled={disabled}
        {...remainingProps}
      >
        {keyArray.map((key: string, index: number) => (
          <StyledKey
            $variant={variant}
            $color={color}
            $disabled={disabled}
            key={`${key}-${index}`}
          >
            {key}
          </StyledKey>
        ))}
      </StyledKeyWrapper>
    );
  },
);
